using System;
using System.Collections.Generic;
using System.Data;
using System.Diagnostics;
using System.Diagnostics.CodeAnalysis;
using System.Globalization;
using System.Security.Principal;
using VideoOS.Installer.Common.Utilities;
using VideoOS.Installer.Interfaces.Content;
using VideoOS.Installer.Logging;
using VideoOS.Installer.ServerPagesSetupPlugin.Properties;
using VideoOS.Installer.UI.Framework;
using VideoOS.Utilities.Database;

namespace VideoOS.Installer.ServerPagesSetupPlugin;

public static class DatabaseComplianceCheck
{
	public static bool NeedsDatabaseComplianceCheck => ProductCompliance.ProductComplianceVersion < ProductComplianceVersion.V1;

	public static void DoDatabaseComplianceCheck(ISqlConnectionManager sqlConnectionManager)
	{
		if (!NeedsDatabaseComplianceCheck)
		{
			return;
		}
		LogManager.Write("DoDatabaseComplianceCheck: Found ProductComplianceVersion = V0 ");
		Version systemVersionFromDatabase = GetSystemVersionFromDatabase(sqlConnectionManager);
		if (systemVersionFromDatabase != null && systemVersionFromDatabase < new Version(20, 3) && SQLHasFipsEnabledOnUpgradeFromNonFipsCompliantVersion(sqlConnectionManager))
		{
			Func<string> func = () => Resources.ErrorMessage_FipsEnabledOnSQLUpgradeTitle;
			Func<ContentLinkText> lookupErrorPageBody = () => new ContentLinkText(Resources.ErrorMessage_FipsEnabledOnSQLUpgrade, (Resources.ErrorMessage_FipsEnabledOnSQLUpgradeLinkText, new Uri("https://support.microsoft.com/en-us/help/4014354/how-to-use-sql-server-2016-in-fips-140-2-compliant-mode")));
			throw new ComplianceException(func(), new DetailedErrorException(func, lookupErrorPageBody, enablePreviousButton: false));
		}
	}

	private static bool SQLHasFipsEnabledOnUpgradeFromNonFipsCompliantVersion(ISqlConnectionManager sqlConnectionManager)
	{
		LogManager.Write("Start check of SQL has FIPS enabled on non FIPS compliant version...");
		string currentDatabaseOwner = GetCurrentDatabaseOwner(sqlConnectionManager);
		WindowsIdentity current = WindowsIdentity.GetCurrent();
		List<string> list = new List<string>();
		using DatabaseConnection databaseConnection = sqlConnectionManager.GetSqlConnection();
		try
		{
			LogManager.Write("Cleanup database before check...");
			list = new List<string>();
			list.Add(FormattableString.Invariant($"IF EXISTS(SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateHardwarePasswordEncryption]') AND [type] = 'FS') DROP FUNCTION [dbo].[UpdateHardwarePasswordEncryption]"));
			list.Add(FormattableString.Invariant($"IF EXISTS(SELECT * FROM sys.assemblies asms WHERE asms.name = N'VideoOS.SqlServer.SqlTypes') DROP ASSEMBLY [VideoOS.SqlServer.SqlTypes]"));
			list.Add(FormattableString.Invariant($"ALTER DATABASE [{databaseConnection.Database}] SET TRUSTWORTHY OFF"));
			list.Add(FormattableString.Invariant($"ALTER AUTHORIZATION ON DATABASE::[{databaseConnection.Database}] TO [{currentDatabaseOwner}]"));
			string sqlCommand = string.Join("\n", list);
			using (DatabaseCommand databaseCommand = GetSqlCommand(databaseConnection, sqlCommand))
			{
				try
				{
					databaseCommand.ExecuteNonQuery();
				}
				catch (DatabaseException ex)
				{
					if (ex.Number != 15110)
					{
						throw;
					}
				}
			}
			LogManager.Write("Cleanup of database before check done!");
			LogManager.Write("Configuring SQL database...");
			list = new List<string>();
			list.Add(FormattableString.Invariant($"ALTER DATABASE [{databaseConnection.Database}] SET TRUSTWORTHY ON"));
			list.Add(FormattableString.Invariant($"USE [{databaseConnection.Database}]"));
			list.Add(FormattableString.Invariant($"ALTER AUTHORIZATION ON DATABASE::[{databaseConnection.Database}] TO [{current.Name}]"));
			sqlCommand = string.Join("\n", list);
			using (DatabaseCommand databaseCommand2 = GetSqlCommand(databaseConnection, sqlCommand))
			{
				try
				{
					databaseCommand2.ExecuteNonQuery();
				}
				catch (DatabaseException ex2)
				{
					if (ex2.Number != 15110)
					{
						throw;
					}
				}
			}
			list = new List<string>();
			list.Add(FormattableString.Invariant($"CREATE ASSEMBLY [VideoOS.SqlServer.SqlTypes]"));
			list.Add(FormattableString.Invariant($"AUTHORIZATION [dbo]"));
			list.Add(FormattableString.Invariant($"FROM "));
			list.Add(FormattableString.Invariant($"WITH PERMISSION_SET = UNSAFE"));
			sqlCommand = string.Join("\n", list);
			using (DatabaseCommand databaseCommand3 = GetSqlCommand(databaseConnection, sqlCommand))
			{
				databaseCommand3.ExecuteNonQuery();
			}
			list = new List<string>();
			list.Add(FormattableString.Invariant($"CREATE FUNCTION [UpdateHardwarePasswordEncryption](@input NVARCHAR(MAX), @hardwareId NVARCHAR(MAX))"));
			list.Add(FormattableString.Invariant($"RETURNS NVARCHAR(MAX)"));
			list.Add(FormattableString.Invariant($"AS"));
			list.Add(FormattableString.Invariant($"EXTERNAL NAME [VideoOS.SqlServer.SqlTypes].[UserDefinedFunctions].[UpdateEncryptionHardwarePassword]"));
			sqlCommand = string.Join("\n", list);
			using (DatabaseCommand databaseCommand4 = GetSqlCommand(databaseConnection, sqlCommand))
			{
				databaseCommand4.ExecuteNonQuery();
			}
			list = new List<string>();
			list.Add(FormattableString.Invariant($"DECLARE @ID GUIDType = '0203b477-ab68-4338-980f-0630dd41b910'"));
			list.Add(FormattableString.Invariant($"DECLARE @result NVARCHAR(max)"));
			list.Add(FormattableString.Invariant($"EXEC @result = UpdateHardwarePasswordEncryption 'gku1Dti21wg71VBsZJyqzX8m4VfzAtx3Lo7ClaBvLngUrrTJU9VUow==', @ID"));
			list.Add(FormattableString.Invariant($"SELECT @result"));
			sqlCommand = string.Join("\n", list);
			try
			{
				using DatabaseCommand databaseCommand5 = GetSqlCommand(databaseConnection, sqlCommand);
				LogManager.Write("Executing check on database...");
				databaseCommand5.ExecuteNonQuery();
				LogManager.Write("Check succeeded!");
			}
			catch (DatabaseException ex3)
			{
				if (ex3.Message.Contains("InvalidOperationException") && ex3.Message.Contains("FIPS"))
				{
					LogManager.Write("Check Failed!");
					LogManager.Write(ex3);
					return true;
				}
				throw;
			}
			return false;
		}
		catch (Exception)
		{
			LogManager.Write("Check of SQL has FIPS enabled on non FIPS compliant version failed!!", TraceEventType.Error);
			throw;
		}
		finally
		{
			LogManager.Write("Cleanup of database after check...");
			list = new List<string>();
			list.Add(FormattableString.Invariant($"IF EXISTS(SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateHardwarePasswordEncryption]') AND [type] = 'FS') DROP FUNCTION [dbo].[UpdateHardwarePasswordEncryption]"));
			list.Add(FormattableString.Invariant($"IF EXISTS(SELECT * FROM sys.assemblies asms WHERE asms.name = N'VideoOS.SqlServer.SqlTypes') DROP ASSEMBLY [VideoOS.SqlServer.SqlTypes]"));
			list.Add(FormattableString.Invariant($"ALTER DATABASE [{databaseConnection.Database}] SET TRUSTWORTHY OFF"));
			list.Add(FormattableString.Invariant($"ALTER AUTHORIZATION ON DATABASE::[{databaseConnection.Database}] TO [{currentDatabaseOwner}]"));
			string sqlCommand = string.Join("\n", list);
			using (DatabaseCommand databaseCommand6 = GetSqlCommand(databaseConnection, sqlCommand))
			{
				try
				{
					databaseCommand6.ExecuteNonQuery();
				}
				catch (DatabaseException ex5)
				{
					if (ex5.Number != 15110)
					{
						LogManager.Write(string.Format(CultureInfo.InvariantCulture, "Error while cleaning up database after check exception is {0}", ex5), TraceEventType.Error);
					}
				}
			}
			LogManager.Write("Cleanup done!");
		}
	}

	private static string GetCurrentDatabaseOwner(ISqlConnectionManager sqlConnectionManager)
	{
		using (DatabaseConnection databaseConnection = sqlConnectionManager.GetSqlConnection())
		{
			using DatabaseCommand databaseCommand = databaseConnection.CreateCommand("SELECT SUSER_SNAME(owner_sid) FROM sys.databases WHERE name = DB_NAME()");
			databaseCommand.CommandType = CommandType.Text;
			using DatabaseDataReader databaseDataReader = databaseCommand.ExecuteReader(CommandBehavior.SingleRow);
			if (databaseDataReader.Read())
			{
				string text = databaseDataReader.GetString(0);
				if (!string.IsNullOrEmpty(text))
				{
					return text;
				}
			}
		}
		return null;
	}

	[SuppressMessage("Microsoft.Security", "CA2100:Review SQL queries for security vulnerabilities", Justification = "Not comming from user input")]
	private static DatabaseCommand GetSqlCommand(DatabaseConnection connection, string sqlCommand)
	{
		DatabaseCommand databaseCommand = connection.CreateCommand();
		databaseCommand.CommandTimeout = 1800;
		databaseCommand.CommandText = sqlCommand;
		return databaseCommand;
	}

	private static Version GetSystemVersionFromDatabase(ISqlConnectionManager sqlConnectionManager)
	{
		using (DatabaseConnection databaseConnection = sqlConnectionManager.GetSqlConnection())
		{
			using DatabaseCommand databaseCommand = databaseConnection.CreateCommand("SELECT [version] FROM [SYSTEM]");
			databaseCommand.CommandType = CommandType.Text;
			using DatabaseDataReader databaseDataReader = databaseCommand.ExecuteReader(CommandBehavior.SingleRow);
			if (databaseDataReader.Read())
			{
				string text = databaseDataReader.GetString(0);
				if (!string.IsNullOrEmpty(text))
				{
					return new Version(text);
				}
			}
		}
		return null;
	}
}
